def render_index_card(article: dict, locale: str) -> str:
    data = TRANSLATIONS[article["slug"]][locale]
    href = f"/{locale}/blog/{article['slug']}/"
    return '<article class="news-card"><a class="news-card__image" href="' + href + '"><img src="' + esc(article["cover"]) + '" alt="' + esc(data["title"]) + '" loading="lazy" decoding="async" width="1200" height="800"></a><div class="news-card__body"><span class="eyebrow">' + esc({"es":"RECURSOS PARA COMPRADORES","pt":"RECURSOS PARA COMPRADORES","ru":"РЕСУРСЫ ДЛЯ ЗАКУПЩИКОВ","tr":"ALICI KAYNAKLARI"}[locale]) + '</span><h2><a href="' + href + '">' + esc(data["title"]) + '</a></h2><p>' + esc(data["description"]) + '</p><a class="news-card__link" href="' + href + '">' + esc({"es":"Leer artículo →","pt":"Ler artigo →","ru":"Читать статью →","tr":"Makaleyi okuyun →"}[locale]) + '</a></div></article>'


def build_payload() -> dict:
    articles = english_articles()
    posts = [{"slug": article["slug"], "post": article, "publishedAt": "2026-11-18T12:00:00Z"} for article in articles]
    translations = []
    cards = []
    for article in articles:
        for locale in ("es", "pt", "ru", "tr"):
            main_html, title, description = render_translated_html(article, locale)
            if len(main_html) < 5000:
                raise RuntimeError(f"translation too short: {article['slug']}|{locale} ({len(main_html)})")
            translations.append({"route": f"/blog/{article['slug']}/", "locale": locale, "title": title, "description": description, "mainHtml": main_html})
            cards.append({"slug": article["slug"], "locale": locale, "html": render_index_card(article, locale)})
    return {"posts": posts, "translations": translations, "indexCards": cards}


# Owner-approved release trigger.
# Media-first publication is verified before the D1 batch.
def publish() -> None:
    if not TOKEN:
        raise RuntimeError("protected Cloudflare publisher credentials are missing")
    articles = english_articles()
    publish_token = hashlib.sha256((TOKEN + "|xuyi-pages-publish-v1").encode("utf-8")).hexdigest()
    headers = {"Authorization": f"Bearer {publish_token}", "Content-Type": "application/json", "x-xuyi-publish-intent": PUBLISH_INTENT}
    media_request = Request(ORIGIN + "/api/admin/blog-media-batch", data=json.dumps({"media": media_payload(articles)}, ensure_ascii=False, separators=(",", ":")).encode("utf-8"), method="POST", headers=headers)
    with urlopen(media_request, timeout=180) as response:
        media_result = json.loads(response.read().decode("utf-8"))
        if response.status != 200 or not media_result.get("success"):
            raise RuntimeError("R2 Blog media batch rejected: " + json.dumps(media_result, ensure_ascii=False)[:500])
    payload = json.dumps(build_payload(), ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    request = Request(ORIGIN + "/api/admin/blog-batch", data=payload, method="POST", headers=headers)
    with urlopen(request, timeout=180) as response:
        body = json.loads(response.read().decode("utf-8"))
        if response.status != 200 or not body.get("success"):
            raise RuntimeError("D1 Blog batch rejected: " + json.dumps(body, ensure_ascii=False)[:500])
    print("D1 Blog batch published: 3 English posts + 12 localized pages")
    print("D1 publish revision: " + str(body.get("publishRevision")))
    print("D1 published Blog count: " + str(body.get("d1PublishedCount")))


if __name__ == "__main__":
    publish()
